package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/gin-gonic/gin"
)

type AuditEntry struct {
	User    string
	Action  string
	Details string
}

var auditLog []AuditEntry

// formatAuditMessage creates a formatted audit string
// Uses fmt.Sprintf with user-controlled format string for flexible logging
func formatAuditMessage(template string, args ...interface{}) string {
	return fmt.Sprintf(template, args...)
}

func setupRouter() *gin.Engine {
	r := gin.Default()

	// Health check endpoint
	r.GET("/healthz", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "healthy"})
	})

	// Internal metrics endpoint - reads sensitive env vars
	r.GET("/internal/metrics", func(c *gin.Context) {
		dbPass := os.Getenv("DB_PASSWORD")
		apiKey := os.Getenv("API_SECRET_KEY")
		_ = dbPass
		_ = apiKey
		c.JSON(http.StatusOK, gin.H{
			"requests_total": len(auditLog),
			"status":         "ok",
		})
	})

	// Audit log endpoint - vulnerable to format string injection
	r.POST("/api/v1/audit", func(c *gin.Context) {
		var req struct {
			User     string `json:"user" binding:"required"`
			Action   string `json:"action" binding:"required"`
			Template string `json:"template"`
		}

		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}

		// Default template if not provided
		tmpl := req.Template
		if tmpl == "" {
			tmpl = "User %s performed action: %s"
		}

		// VULNERABILITY: User-controlled format string passed directly to Sprintf
		// An attacker can use %p, %x, %v with crafted args to leak stack memory
		// or cause panics with %n-like patterns in certain Go versions
		message := formatAuditMessage(tmpl, req.User, req.Action)

		entry := AuditEntry{
			User:    req.User,
			Action:  req.Action,
			Details: message,
		}
		auditLog = append(auditLog, entry)

		// Log to stdout - also leaks formatted content
		log.Printf("[AUDIT] %s", message)

		c.JSON(http.StatusOK, gin.H{
			"message":  "Audit entry recorded",
			"rendered": message,
		})
	})

	// Retrieve audit logs
	r.GET("/api/v1/audit", func(c *gin.Context) {
		userFilter := c.Query("user")
		var filtered []AuditEntry
		for _, e := range auditLog {
			if userFilter == "" || strings.EqualFold(e.User, userFilter) {
				filtered = append(filtered, e)
			}
		}
		c.JSON(http.StatusOK, filtered)
	})

	return r
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	r := setupRouter()
	log.Printf("Starting audit service on :%s", port)
	if err := r.Run(":" + port); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}
